// The single source of truth for every tool listed on CodeStack.
// `icon` is a Simple Icons slug. Run `npm run icons` after adding a new one.

export type Audience = "develop" | "design"

export type CategoryId =
  | "frameworks"
  | "languages"
  | "mobile"
  | "backend"
  | "databases"
  | "devtools"
  | "hosting"
  | "services"
  | "payments"
  | "ai"
  | "design-tools"
  | "inspiration"
  | "typography"
  | "icons"
  | "color"
  | "assets"
  | "mockups"
  | "components"
  | "motion"
  | "3d"

export interface Category {
  id: CategoryId
  name: string
  audience: Audience
  /** Also listed under the other audience, e.g. AI tools serve designers and developers alike. */
  alsoFor?: Audience
  tagline: string
}

export interface Tool {
  name: string
  url: string
  description: string
  kind: string
  category: CategoryId
  icon?: string
  openSource?: boolean
  paid?: boolean
  /** Free tier with optional paid extras. */
  freemium?: boolean
  /** What the free tier includes, checked against the provider's own pricing page. */
  free?: string
}

